local Item = {}
Item.__index = Item

function Item.new(name, count)
  return setmetatable({ name = name, count = count }, Item)
end

function Item.__lt(left, right)
  if left.count == right.count then
    return left.name < right.name
  end
  return left.count < right.count
end

function Item.__tostring(item)
  return string.format("%s:%d", item.name, item.count)
end

local items = {
  Item.new("nuts", 2),
  Item.new("bolts", 2),
  Item.new("washers", 1),
}
table.sort(items)
for _, item in ipairs(items) do
  print(tostring(item))
end
